import{_ as a,o as i,c as o,al as r}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"ROS 2","description":"","frontmatter":{},"headers":[],"relativePath":"zh/ros2/index.md","filePath":"zh/ros2/index.md"}'),t={name:"zh/ros2/index.md"};function s(n,e,l,d,c,h){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h1><p><a href="https://docs.ros.org/en/humble/#" target="_blank" rel="noreferrer">ROS 2</a>是一款功能强大的通用机器人开发库，可与 PX4 自动驾驶仪搭配使用，以开发功能丰富的无人机应用程序。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>小提示 PX4 开发团队强烈建议您使用此 ROS 版本，或将现有系统迁移至此 ROS 版本！</p><p>这是最新版本的 <a href="https://www.ros.org/" target="_blank" rel="noreferrer">ROS</a>(机器人操作系统)。 它在 ROS “1” 的基础上进行了显著改进，尤其能够实现与 PX4 更深度、更低延迟的集成。</p></div><p>ROS的优势在于拥有活跃的开发者生态系统 —— 该生态系统致力于解决各类常见的机器人技术问题，同时还能调用其他为 Linux 系统编写的软件库。 例如，它可以用于 <a href="./../computer_vision/">计算机试图</a> 解决问题。</p><p>ROS 2 能够实现与 PX4 极深度的集成，你可以在 ROS 2 中创建飞行模式，这些模式与 PX4 内部原生飞行模式毫无区别；同时还能以高速率直接读取和写入 PX4 内部的 uORB 主题。 （尤其）建议在以下场景中使用：从伴飞计算机进行控制与通信（且低延迟至关重要时）、需借助 Linux 系统的现有库时，或编写新的高级飞行模式时。</p><p>Communication between ROS 2 and PX4 can leverage two independent middlewares:</p><ul><li><a href="./../middleware/uxrce_dds">XRCE-DDS protocol</a> — Original middleware. More tested and included by default in most PX4 builds.</li><li><a href="./../middleware/zenoh">Zenoh protocol</a> — Must be manually added and enabled to most PX4 builds.</li></ul><p>The middlewares expose PX4 <a href="./../msg_docs/">uORB messages</a> as ROS 2 messages and types, effectively allowing direct access to PX4 from ROS 2 workflows and nodes. The middlewares use uORB message definitions to generate code to serialise and deserialise the messages heading in and out of PX4. 这些相同的消息定义也用于 ROS 2 应用程序中以便能够解析这些消息。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>ROS 2 can also connect with PX4 using <a href="https://github.com/mavlink/mavros/tree/ros2/mavros" target="_blank" rel="noreferrer">MAVROS</a> instead of XRCE-DDS / Zenoh. 该选项受 MAVROS 项目支持（本文档未对此进行说明）。</p></div><p>To use the <a href="./../ros2/user_guide">ROS 2</a> over XRCE-DDS / Zenoh effectively, you must (at time of writing) have a reasonable understanding of the PX4 internal architecture and conventions, which differ from those used by ROS. 我们计划近期提供ROS 2 API 以对 PX4 的特性进行封装，并举例说明它们的用途。</p><h2 id="topics" tabindex="-1">Topics <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics&quot;">​</a></h2><p>本节的主要主题是：</p><ul><li><a href="./../ros2/user_guide">ROS 2 用户指南</a>: PX4 视角下的 ROS 2，包括安装、设置和如何构建与 PX4 通信的 ROS 2 应用。</li><li><a href="./../ros2/offboard_control">ROS 2 离板控制实例</a>：一个 C++ 教程示例显示如何在 [离板模式] (../flight_modes/offboard.md) 中使用 ROS 2 节点进行位置控制。</li><li><a href="./../ros2/multi_vehicle">ROS 2 Multi Vehicle Simulation</a>: Instructions for connecting to multiple PX4 simulations via single ROS 2 agent.</li><li><a href="./../ros2/px4_ros2_interface_lib">PX4 ROS 2 Interface Library</a>: A C++ library that simplifies interacting with PX4 from ROS 2. Can be used to create and register flight modes written using ROS 2 and send position estimates from ROS 2 applications such as a VIO system.</li><li><a href="./../ros2/px4_ros2_msg_translation_node">ROS 2 Message Translation Node</a>: A ROS 2 message translation node that enables communication between PX4 and ROS 2 applications that were compiled with different sets of messages versions.</li></ul><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="./../middleware/uxrce_dds">XRCE-DDS (PX4-ROS 2/DDS Bridge)</a>: PX4 middleware leveranging micro XRCE-DDS for connecting to ROS 2.</li><li><a href="./../middleware/zenoh">Zenoh (PX4 ROS 2)</a>: PX4 middleware leveraging Zenoh pico for connecting to ROS 2.</li></ul>',15)])])}const u=a(t,[["render",s]]);export{f as __pageData,u as default};
